import hid
import time

VID = 0x258A
PID = 0x0049

# 1. Mapear los Data Fragments de Wireshark
hex_2837 = "0583c6000000"  # Paquete 2837 (6 bytes)
hex_2841 = ""  # Bloque 1 (1032 bytes)
hex_2843 = ""  # Bloque 2
hex_2845 = ""  # Bloque 3
hex_2869 = ""  # Bloque de Cierre / Commit

def preparar_payload(hex_str, target_len):
    raw_bytes = bytes.fromhex(hex_str)
    if len(raw_bytes) < target_len:
        return list(raw_bytes) + [0x00] * (target_len - len(raw_bytes))
    return list(raw_bytes[:target_len])

# Preparamos las cargas útiles
payload_2837 = preparar_payload(hex_2837, 6)
payload_2841 = preparar_payload(hex_2841, 1032)
payload_2843 = preparar_payload(hex_2843, 1032)
payload_2845 = preparar_payload(hex_2845, 1032)
payload_2869 = preparar_payload(hex_2869, 1032)

# Función auxiliar para enviar a la colección correspondiente
def enviar_a_coleccion(col_name, payload):
    target_path = None
    for dev in hid.enumerate(VID, PID):
        valor = col_name.encode()
        if col_name.encode() in dev['path']:
            target_path = dev['path']
            break
            
    if not target_path:
        print(f"Error: No se encontró la colección {col_name}")
        return
        
    d = hid.device()
    d.open_path(target_path)
    try:
        bytes_sent = d.send_feature_report(payload)
        print(f"-> Enviado en {col_name}: {bytes_sent} bytes")
    except Exception as e:
        print(f"Error en {col_name}: {e}")
    finally:
        d.close()

# -------------------------------------------------------------
# EJECUCIÓN DE LA SECUENCIA COMPLETA
# -------------------------------------------------------------
print("Iniciando secuencia de actualización...")

# PASO 1: Handshake Inicial (2837) -> Col05
enviar_a_coleccion('Col05', payload_2837)
time.sleep(0.02)

# PASO 2: Carga de Datos Principal (2841) -> Col06
enviar_a_coleccion('Col06', payload_2841)
time.sleep(0.02)

# PASO 3: Réplicas/Perfiles adicionales (2843 y 2845) -> Col06
enviar_a_coleccion('Col06', payload_2843)
time.sleep(0.02)

enviar_a_coleccion('Col06', payload_2845)
time.sleep(0.02)

# PASO 4: Comando Final / Confirmación (2869) -> Col06 (o Col05 si wValue era 0x0305)
enviar_a_coleccion('Col06', payload_2869)

print("\n¡Secuencia finalizada! Comprueba el teclado.")
